### FUNCION: saveAndExitEditMode
```js
function saveAndExitEditMode(event) {
    const cell = event.currentTarget;
    const coord = cell.dataset.coord;

    if (!coord) return;

    // 1. Capture the raw text content from the editable div
    let rawValue = cell.textContent.trim();

    // 2. Update the model (This saves the typed value)
    spreadsheetData[coord].value = rawValue;

    // 3. Recalculate dependencies and update UI to reflect saved state
    recalculateDependencies(coord);
    updateCellUI(coord);

    // 4. Exit edit mode by removing contenteditable attribute
    cell.setAttribute('contenteditable', 'false');
}
```

### FUNCION: handleCellClick
```js
function handleCellClick(event) {
    const cell = event.currentTarget;
    const coord = cell.dataset.coord;

    if (!coord) return;

    // 1. Update selection state (R6, R7)
    clearSelection();
    selectCell(cell);

    // 2. Enable editing mode and focus the element for immediate editing (R10)
    // We set contenteditable to true on click so the user can type immediately.
    cell.setAttribute('contenteditable', 'true');
    cell.focus();
}
```

### FUNCION: handleCellInput
```js
function handleCellInput(event) {
    const cell = event.currentTarget;
    const coord = cell.dataset.coord;
    let rawValue = event.target.value;

    // Update the model with the new raw value
    spreadsheetData[coord].value = rawValue;

    // If the user typed something, we must recalculate dependencies (R4)
    recalculateDependencies(coord);
}
