/**
 * Handles the click event on a cell to select it and enable editing.
 * @param {Event} event - The click event object.
 */
function handleCellClick(event) {
    const cell = event.currentTarget;
    if (!cell || cell.classList.contains('hidden')) return;

    // 1. Clear previous selection and edit state
    clearSelection();

    // 2. Select the new cell
    selectCell(cell);

    // 3. Make the cell editable and focus on it (FIX)
    cell.setAttribute('contenteditable', 'true');
    cell.focus();
}

/**
 * Handles input changes when a user types into an editable cell.
 * @param {Event} event - The input event object.
 */
function handleCellInput(event) {
    const target = event.target;
    // Check if the target is an editable cell within the grid area
    if (target.classList.contains('cell') && target.getAttribute('contenteditable') === 'true') {
        const coord = getCoord(target);
        if (coord) {
            updateCellUI(coord, target.innerText);
            saveState();
            // Recalculate dependencies if the input is numeric or formula-like
            recalculateDependencies(coord);
        }
    }
}

