### FUNCION: calculateFormula
```js
function calculateFormula(formulaString) {
    if (!formulaString || typeof formulaString !== 'string' || !formulaString.startsWith('=')) {
        return formulaString; // Not a formula or empty
    }

    let formula = formulaString.substring(1).trim();
    let result = null;

    // 1. Handle SUMA function: =SUMA(range)
    const sumMatch = formula.match(/^SUMA\(([^)]+)\)$/i);
    if (sumMatch) {
        const rangeString = sumMatch[1];
        let coords = [];

        // Simple parsing for ranges like A1:B2 or comma-separated lists
        const parts = rangeString.split(/,\s*|\s+:\s+/).filter(p => p);

        for (const part of parts) {
            if (part.includes(':')) {
                // Handle range format (e.g., A1:A3)
                const [startCoord, endCoord] = part.split(':').map(c => c.trim());
                let startCol = getColumnIndexFromCoord(startCoord);
                let startRow = getRowNumberFromCoord(startCoord);
                let endCol = getColumnIndexFromCoord(endCoord);
                let endRow = getRowNumberFromCoord(endCoord);

                // Iterate through the rectangular range
                for (let r = Math.min(startRow, endRow); r <= Math.max(startRow, endRow); r++) {
                    for (let c = Math.min(startCol, endCol); c <= Math.max(startCol, endCol); c++) {
                        coords.push(getCoord(c, r));
                    }
                }
            } else {
                // Handle single cell coordinate (e.g., A1)
                coords.push(part.trim());
            }
        }

        let sum = 0;
        for (const coord of coords) {
            const value = getNumericValue(coord);
            if (!isNaN(value)) {
                sum += value;
            }
        }
        return sum.toString();
    }

    // 2. Handle basic arithmetic operations: A1-B1, A1*B1, etc.
    try {
        // Replace cell references (A1, B2) with their actual numeric values
        let expression = formula;
        const regex = /([A-Z]+[0-9]+)/g; // Matches standard coordinate format like A1, J20

        expression = expression.replace(regex, (match) => {
            const value = getNumericValue(match);
            return isNaN(value) ? '0' : value;
        });

        // Use eval() for safe evaluation of the arithmetic string
        // Note: In a real production app, this would require a dedicated math parser library.
        // For this scope, we assume simple arithmetic operations are sufficient.
        return (eval(expression)).toString();

    } catch (e) {
        console.error("Error evaluating formula:", e);
        return "ERROR"; // Return error if calculation fails
    }
}
