### FUNCION: getColumnIndexFromCoord
```js
function getColumnIndexFromCoord(coord) {
    const match = coord.match(/([A-Z]+)([0-9]+)/i);
    if (!match) return null;
    const colStr = match[1].toUpperCase();
    let index = 0;
    for (let i = 0; i < colStr.length; i++) {
        index = index * 26 + (colStr.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
    }
    // Convert 1-based column number to 0-based index
    return index - 1;
}
```

### FUNCION: getRowNumberFromCoord
```js
function getRowNumberFromCoord(coord) {
    const match = coord.match(/([A-Z]+)([0-9]+)/i);
    if (!match || !match[2]) return null;
    return parseInt(match[2], 10);
}
```

### FUNCION: getCoord
```js
function getCoord(colIndex, rowIndex) {
    // Helper function to convert (index, number) back to A1 format
    let col = '';
    let num = rowIndex;
    while (num > 0) {
        let remainder = (num - 1) % 26;
        col = String.fromCharCode(remainder + 'A') + col;
        num = Math.floor((num - 1) / 26);
    }
    return `${col}${rowIndex}`;
}
```

