function getCellElement(coord) {
    // Finds the cell element by its data-coord attribute
    const cells = document.querySelectorAll('.cell');
    for (const cell of cells) {
        if (cell.dataset.coord === coord) {
            return cell;
        }
    }
    return null;
}
