function saveState() {
    // Collect data from all editable cells
    const state = {};
    document.querySelectorAll('.cell[contenteditable="true"]').forEach(cell => {
        const coord = cell.dataset.coord;
        if (coord) {
            state[coord] = {
                value: cell.textContent.trim(),
                isFormula: cell.dataset.isFormula || 'false' // Preserve formula status if needed
            };
        }
    });

    // Save the state object to localStorage
    localStorage.setItem('spreadsheetState', JSON.stringify(state));
}
