    let index = 0;
    for (let i = 0; i < colStr.length; i++) {
        index = index * 26 + (colStr.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
    }
    return index - 1;
}

/** Converts A1 coordinate string to row number */
function getRowNumberFromCoord(coord) {
    const match = coord.match(/([A-Z]+)([0-9]+)/i);
