```javascript
/**
 * Obtiene las coordenadas (colIndex, rowIndex) de un elemento dado.
 * @param {HTMLElement} element - El elemento a analizar.
 * @returns {{colIndex: number, rowIndex: number}} Las coordenadas.
 */
function getCoord(element) {
    const colHeader = element.closest('.col-header');
    const rowLabel = element.closest('.row-label');

    let colIndex = -1;
    let rowIndex = -1;

    if (colHeader) {
        // Calcular el índice de columna basado en la posición relativa dentro del contenedor de etiquetas de columna.
        const labels = document.getElementById('column-labels').querySelectorAll('.label');
        for (let i = 0; i < labels.length; i++) {
            if (labels[i] === colHeader) {
                colIndex = i - 1; // Restamos 1 por el div del corner-cell
                break;
            }
        }
    }

    if (rowLabel) {
        // Calcular el índice de fila basado en la posición relativa dentro del contenedor de etiquetas de fila.
        const rows = document.getElementById('grid-area').querySelectorAll('.row-label');
        for (let i = 0; i < rows.length; i++) {
            if (rows[i] === rowLabel) {
                rowIndex = i + 1; // Las filas comienzan en el índice 1
                break;
            }
        }
    }

    return { colIndex, rowIndex };
}

/**
 * Obtiene el elemento de la celda dado sus coordenadas.
 * @param {{colIndex: number, rowIndex: number}} coord - Coordenadas (0-based para columna, 1-based para fila).
 * @returns {HTMLElement | null} El elemento de la celda o null si no existe.
 */
function getCellElement(coord) {
    if (!coord || typeof coord.colIndex === 'undefined' || typeof coord.rowIndex === 'undefined') {
        return null;
    }

    // Las columnas en el DOM son 0-based (A=0, B=1, ...).
    // Los índices de fila en el DOM son 1-based (Fila 1, Fila 2, ...).
    const colIndex = coord.colIndex;
    const rowIndex = coord.rowIndex;

    if (colIndex < 0 || colIndex >= 10 || rowIndex < 1 || rowIndex > 20) {
        return null;
    }

    // Buscamos el elemento de la celda directamente en el contenedor principal del grid.
    const cell = document.querySelector(`[data-col="${String.fromCharCode(65 + colIndex)}"][data-row="${rowIndex}"]`);
    return cell || null;
}

/**
 * Guarda el estado actual de la hoja de cálculo (valores, fórmulas y colores).
 * @returns {object} Un objeto con el estado guardado.
 */
function saveState() {
    const state = {};
    state.data = {}; // Almacena valores/fórmulas por coordenada "A1": "valor"
    state.colors = {}; // Almacena colores de fondo por coordenada

    // Iterar sobre todas las celdas visibles para guardar su estado
    document.querySelectorAll('.cell-grid .cell').forEach(cell => {
        const coord = getCoord(cell);
        if (coord && coord.colIndex !== -1 && coord.rowIndex !== -1) {
            const key = `${String.fromCharCode(65 + coord.colIndex)}${coord.rowIndex}`;

            // Guardar valor/fórmula
            state.data[key] = cell.dataset.value || '';
            if (cell.dataset.formula) {
                state.data[key] = cell.dataset.formula;
            } else if (cell.innerText && !isNaN(parseFloat(cell.innerText))) {
                 // Si es un número y no tiene fórmula, lo guardamos como valor numérico/texto simple
                 state.data[key] = cell.innerText;
            }

            // Guardar color de fondo
            const bgColor = getComputedStyle(cell).backgroundColor;
            state.colors[key] = rgbToHex(bgColor);
        }
    });

    return state;
}

/**
 * Convierte un valor RGB (string) a su equivalente hexadecimal (#RRGGBB).
 * @param {string} rgbColor - Color en formato 'rgb(r, g, b)'.
 * @returns {string} Color en formato '#RRGGBB'.
 */
function rgbToHex(rgbColor) {
    if (!rgbColor || rgbColor === 'rgba(0, 0, 0, 0)') return '#ffffff'; // Default background if no color is set

    const match = rgbColor.match(/\d+/g);
    if (match && match.length >= 3) {
        const r = parseInt(match[0]);
        const g = parseInt(match[1]);
        const b = parseInt(match[2]);
        return "#" + ((1 << 24) + (r < 15 ? 1 : 0) * (1 << 16) + (g < 15 ? 1 : 0) * (1 << 8) + (b < 15 ? 1 : 0)).toString(16).slice(1);
    }
    return '#ffffff'; // Fallback
}

/**
 * Carga el estado guardado en la hoja de cálculo.
 * @param {object} state - El objeto de estado a cargar.
 */
function loadState(state) {
    if (!state || !state.data) return;

    // 1. Limpiar UI y restablecer estilos/valores
    document.querySelectorAll('.cell-grid .cell').forEach(cell => {
        cell.innerText = '';
        cell.dataset.value = '';
        cell.dataset.formula = '';
        cell.style.backgroundColor = ''; // Reset background color
    });

    // 2. Restaurar datos y fórmulas
    for (const key in state.data) {
        if (!state.data[key]) continue;

        const cell = document.querySelector(`[data-col="${String.fromCharCode(65 + getColIndexFromKey(key))}"][data-row="${getRowNumFromKey(key)}"]`);
        if (cell) {
            let value = state.data[key];

            // Determinar si es fórmula o valor simple
            if (value.toUpperCase().startsWith('=')) {
                cell.dataset.formula = value;
                cell.innerText = ''; // No mostrar la fórmula en el texto visible
            } else {
                cell.dataset.value = value;
                cell.innerText = value;
            }
        }
    }

    // 3. Restaurar colores de fondo
    for (const key in state.colors) {
        if (!state.colors[key]) continue;
        const cell = document.querySelector(`[data-col="${String.fromCharCode(65 + getColIndexFromKey(key))}"][data-row="${getRowNumFromKey(key)}"]`);
        if (cell) {
            cell.style.backgroundColor = state.colors[key];
        }
    }

    // 4. Recalcular dependencias después de cargar el estado
    recalculateDependencies();
}

/**
 * Helper para obtener el índice de columna a partir de la clave "A1", "B5", etc.
 * @param {string} key - La clave (ej: "C3").
 * @returns {number} El índice de columna 0-based.
 */
function getColIndexFromKey(key) {
    const colChar = key[0];
    return colChar.charCodeAt(0) - 'A'.charCodeAt(0);
}

/**
 * Helper para obtener el número de fila a partir de la clave "A1", "B5", etc.
 * @param {string} key - La clave (ej: "C3").
 * @returns {number} El número de fila 1-based.
 */
function getRowNumFromKey(key) {
    return parseInt(key.substring(1));
}


/**
 * Actualiza la interfaz de usuario de una celda específica.
 * Esto incluye el valor, si está seleccionada o no, y su estado visual.
 * @param {{colIndex: number, rowIndex: number}} coord - Coordenadas a actualizar.
 */
function updateCellUI(coord) {
    const cell = getCellElement(coord);
    if (!cell) return;

    // 1. Actualizar el valor y la fórmula (si se ha guardado en el estado o si es un cálculo)
    let valueToDisplay = '';
    let formulaString = null;

    // Si estamos actualizando después de una recalculación, asumimos que el valor ya está calculado/establecido.
    if (cell.dataset.formula) {
        formulaString = cell.dataset.formula;
        valueToDisplay = getNumericValue(coord); // Mostrar resultado del cálculo
    } else if (cell.dataset.value !== undefined) {
        const value = cell.dataset.value;
        if (typeof value === 'number' || !isNaN(parseFloat(value))) {
            valueToDisplay = value;
        } else {
            valueToDisplay = String(value);
        }
    }

    // 2. Actualizar el DOM
    cell.dataset.formula = formulaString || '';
    cell.dataset.value = valueToDisplay;
    cell.innerText = valueToDisplay;

    // 3. Manejar la selección visual (esto se hace mejor en selectCell, pero lo mantenemos aquí por consistencia)
}

/**
 * Obtiene el valor numérico de una celda o calcula su resultado si es fórmula.
 * @param {{colIndex: number, rowIndex: number}} coord - Coordenadas.
 * @returns {number|string} El valor numérico o la cadena de texto del resultado.
 */
function getNumericValue(coord) {
    const cell = getCellElement(coord);
    if (!cell) return '';

    let value = cell.dataset.value;

    // Si es una fórmula, calcular el resultado
    if (cell.dataset.formula && !isNaN(parseFloat(cell.dataset.formula))) {
        try {
            const result = calculateFormula(cell.dataset.formula);
            return typeof result === 'number' ? result : String(result);
        } catch (e) {
            console.error("Error calculating formula:", e);
            return "ERROR";
        }
    }

    // Si es un valor simple, intentar parsear como número
    const numValue = parseFloat(value);
    if (!isNaN(numValue)) {
        return numValue;
    }

    return value || '';
}


/**
 * Evalúa una cadena de fórmula (ej: "=A1+B2").
 * @param {string} formulaString - La fórmula a evaluar.
 * @returns {number|string} El resultado del cálculo o la fórmula si falla.
 */
function calculateFormula(formulaString) {
    let expression = formulaString;

    // Reemplazar referencias de celda (A1, B2...) por sus valores numéricos reales.
    const cellRegex = /([A-Z]+[0-9]+)/g;
    expression = expression.replace(cellRegex, (match) => {
        const coord = getCoord(document.querySelector(`[data-col="${match[0][0]}"][data-row="${match[0].substring(1)}"]`));
        if (coord && coord.colIndex !== -1 && coord.rowIndex !== -1) {
            return getNumericValue(coord);
        }
        return match; // Si no se encuentra, mantener la referencia original
    });

    try {
        // Usamos eval con precaución, pero es necesario para evaluar expresiones matemáticas complejas en JS puro.
        const result = Function(`return ${expression}`)();
        if (typeof result === 'number') {
            return result;
        }
        return String(result);
    } catch (e) {
        console.error("Formula evaluation error:", e);
        return "ERROR";
    }
}

/**
 * Recalcula todas las celdas que dependen de cualquier cambio en la hoja.
 */
function recalculateDependencies() {
    let changedCoord = null;
    // En un entorno real, solo se recalcularía lo afectado por 'changedCoord'. 
    // Aquí, para simplificar y asegurar el funcionamiento tras carga/cambio general, iteramos sobre todas las celdas.

    document.querySelectorAll('.cell-grid .cell').forEach(cell => {
        const coord = getCoord(cell);
        if (coord && cell.dataset.formula) {
            // Forzar la actualización de UI para reflejar el nuevo cálculo
            updateCellUI(coord);
        }
    });
}

/**
 * Selecciona una celda específica, actualizando la interfaz y el estado visual.
 * @param {HTMLElement} cellElement - El elemento DOM de la celda a seleccionar.
 */
function selectCell(cellElement) {
    // 1. Deseleccionar cualquier otra celda
    clearSelection();

    // 2. Seleccionar la nueva celda
    cellElement.classList.add('selected');

    // 3. Actualizar el estado de selección en los controles (si aplica)
    const coord = getCoord(cellElement);
    if (coord) {
        document.getElementById('btn-clear-selection').disabled = false;
    }

    // 4. Forzar la actualización visual para asegurar que se muestre el valor correcto
    updateCellUI(getCoord(cellElement));
}


/**
 * Limpia la selección de cualquier celda, removiendo clases y actualizando UI.
 */
function clearSelection() {
    document.querySelectorAll('.cell-grid .cell').forEach(cell => {
        cell.classList.remove('selected');
    });

    // Deshabilitar botones si no hay selección activa (aunque esto debería ser manejado por el evento de clic)
    document.getElementById('btn-clear-selection').disabled = true;
