 * @param {Event} event - El evento de input/change.
 */
function handleCellInput(event) {
    const target = event.target;
    if (!target.classList.contains('cell')) return;

    const coord = getCoord(target);
    if (!coord || coord.colIndex === -1) return;

    // 1. Actualizar el valor en el dataset y el texto visible
    let newValue = target.innerText.trim();

    // Si se está editando, capturamos el nuevo valor del input (aunque aquí usamos innerText para simplificar).
    if (event.type === 'change' || event.type === 'blur') {
        target.dataset.value = newValue;
    } else if (event.type === 'input') {
         // Si es un input directo, actualizamos el dataset inmediatamente
        target.dataset.value = newValue;
    }

    // 2. Recalcular dependencias y actualizar UI de la celda misma
    recalculateDependencies();
}


