    document.getElementById('btn-clear-selection').addEventListener('click', clearSelection);
    document.getElementById('btn-delete-column').addEventListener('click', deleteColumn);
    document.getElementById('btn-delete-row').addEventListener('click', deleteRow);
}

/**
 * Inicializa la aplicación al cargar el script.
 */
function init() {
    // 1. Configurar listeners de eventos
    setupEventListeners();

    // 2. Construir la cuadrícula y añadir listeners a las celdas
    initializeGrid();

    // 3. Cargar estado (si existe) o inicializar con valores por defecto
    const savedState = localStorage.getItem('spreadsheetState');
    if (savedState) {
        try {
            const state = JSON.parse(savedState);
            loadState(state);
        } catch (e) {
            console.warn("Could not load previous state:", e);
        }
    } else {
        // Si no hay estado, inicializar con un estado vacío para asegurar que los cálculos funcionen desde el inicio.
        const emptyState = { data: {}, colors: {} };
        loadState(emptyState); 
    }
}

// Ejecutar la inicialización cuando el DOM esté completamente cargado
document.addEventListener('DOMContentLoaded', init);
