function calculateFormula(formulaString) {
    if (!formulaString || !formulaString.startsWith('=')) {
        return formulaString; // Not a formula or empty
    }

    let expression = formulaString.substring(1).trim();
    const references = [];
    // Regex to find cell references (e.g., A1, B20) - assumes standard column letters and row numbers
    const cellRefRegex = /([A-Z]+[0-9]+)/g;

    let match;
    while ((match = cellRefRegex.exec(expression)) !== null) {
        references.push(match[0]);
    }

    // Replace all found references with their numeric values
    let resolvedExpression = expression;
    for (const ref of references) {
        const coord = getCoordFromReference(ref); // Helper function needed to convert A1 -> {col, row}
        if (coord && getNumericValue(coord) !== undefined) {
            // Use a regex replacement with word boundaries (\b) to ensure we replace whole tokens only
            resolvedExpression = resolvedExpression.replace(new RegExp('\\b' + ref + '\\b', 'g'), getNumericValue(coord));
        } else {
            console.warn(`Could not resolve reference: ${ref}`);
        }
    }

    try {
        // Use Function constructor for safe evaluation context (safer than direct eval)
        const result = new Function('return ' + resolvedExpression)();
        if (isNaN(result) || !isFinite(result)) {
            return "Error"; // Handle calculation errors
        }
        return result;
    } catch (e) {
        console.error("Formula evaluation error:", e);
        return "Error";
    }
}

// Helper function to convert A1 notation to coordinates {colIndex, rowIndex}
function getCoordFromReference(reference) {
    const colLetters = reference.match(/[A-Z]+/)[0];
    const rowNumber = parseInt(reference.match(/[0-9]+/)[0]);

    if (isNaN(rowNumber)) return null;

    let colIndex = 0;
    for (let i = 0; i < colLetters.length; i++) {
