```javascript
/**
 * Helper function to convert A1 notation (e.g., "A1") into a coordinate object {colIndex, rowIndex}.
 * This is necessary because the regex matching in calculateFormula needs this helper.
 */
function getCoordFromReference(reference) {
    const colLetters = reference.match(/[A-Z]+/);
    const rowNumberStr = reference.match(/[0-9]+/);

    if (!colLetters || !rowNumberStr) return null;

    const colLettersMatch = colLetters[0];
    const rowNumber = parseInt(rowNumberStr[0]);

    if (isNaN(rowNumber)) return null;

    let colIndex = 0;
    for (let i = 0; i < colLettersMatch.length; i++) {
        colIndex = colIndex * 26 + (colLettersMatch.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
    }
    // Convert 1-based column index to 0-based array index
    const colIdx = colIndex - 1;

    return { colIndex: colIdx, rowIndex: rowNumber - 1 };
}


function getCoord(colIndex, rowIndex) {
    if (colIndex < 0 || rowIndex < 0) return null;
    return `${String.fromCharCode('A'.charCodeAt(0) + colIndex)}${rowIndex + 1}`;
}

function getCellElement(coord) {
    const [colLetter, rowNumber] = coord.toUpperCase().split('');
    if (!colLetter || !rowNumber) return null;

    // Calculate column index (A=0, B=1, ...)
    let colIndex = colLetter.charCodeAt(0) - 'A'.charCodeAt(0);
    const rowIndex = parseInt(rowNumber) - 1;

    if (colIndex < 0 || rowIndex < 0) return null;

    return document.querySelector(`[data-coord="${coord}"]`);
}

function saveState() {
    const state = {};
    state.spreadsheetData = JSON.stringify(spreadsheetData);
    state.columnVisibility = Array.from(document.querySelectorAll('.col-header')).map(el => ({
        col: el.dataset.col,
        visible: !el.classList.contains('hidden')
    }));
    state.rowVisibility = Array.from(document.querySelectorAll('.row-label')).map(el => ({
        row: el.dataset.row,
        visible: !el.classList.contains('hidden')
    }));
    return state;
}

function loadState(state) {
    if (!state || !state.spreadsheetData) return false;

    try {
        // 1. Load Data Model
        Object.assign(spreadsheetData, JSON.parse(state.spreadsheetData));

        // 2. Restore Visibility
        document.querySelectorAll('.col-header').forEach(el => {
            const colState = state.columnVisibility.find(c => c.col === el.dataset.col);
            if (colState) {
                el.classList.toggle('hidden', !colState.visible);
            }
        });

        document.querySelectorAll('.row-label').forEach(el => {
            const rowState = state.rowVisibility.find(r => r.row === el.dataset.row);
            if (rowState) {
                el.classList.toggle('hidden', !rowState.visible);
            }
        });

        // 3. Update UI for all cells and labels
        recalculateAll();
        return true;
    } catch (e) {
        console.error("Error loading state:", e);
        return false;
    }
}

function updateCellUI(coord) {
    const cellElement = getCellElement(coord);
    if (!cellElement) return;

    const data = spreadsheetData[coord];
    if (!data) return;

    // Update content and attributes
    cellElement.textContent = data.displayValue !== null ? data.displayValue : '';
    cellElement.dataset.formula = data.formula || '';
    cellElement.setAttribute('contenteditable', 'true'); // Ensure it's editable for focus/input handling

    // Apply color
    const bgColor = data.color || '#ffffff';
    cellElement.style.backgroundColor = bgColor;
}

function getNumericValue(coord) {
    const cellElement = getCellElement(coord);
    if (!cellElement) return undefined;

    const rawValue = spreadsheetData[coord].value;

    // Check if the value is a formula and calculate it first
    if (spreadsheetData[coord].formula && !isNaN(parseFloat(spreadsheetData[coord].formula]))) {
        try {
            const calculatedValue = calculateFormula(spreadsheetData[coord].formula);
            return parseFloat(calculatedValue) || 0;
        } catch (e) {
            console.error("Error calculating numeric value:", e);
            return undefined;
        }
    }

    // Attempt to parse the raw value as a number
    const num = parseFloat(rawValue);
    return isNaN(num) ? undefined : num;
}

function calculateFormula(formulaString) {
    if (!formulaString || !formulaString.startsWith('=')) {
        return formulaString; // Not a formula or empty
    }

    let expression = formulaString.substring(1).trim();
    const references = [];
    // Regex to find cell references (e.g., A1, B20) - assumes standard column letters and row numbers
    const cellRefRegex = /([A-Z]+[0-9]+)/g;

    let match;
    while ((match = cellRefRegex.exec(expression)) !== null) {
        references.push(match[0]);
    }

    // Replace all found references with their numeric values
    let resolvedExpression = expression;
    for (const ref of references) {
        const coord = getCoordFromReference(ref); // Helper function needed to convert A1 -> {col, row}
        if (coord && getNumericValue(coord) !== undefined) {
            // Use a regex replacement with word boundaries (\b) to ensure we replace whole tokens only
            resolvedExpression = resolvedExpression.replace(new RegExp('\\b' + ref + '\\b', 'g'), getNumericValue(coord));
        } else {
            console.warn(`Could not resolve reference: ${ref}`);
        }
    }

    try {
        // Use Function constructor for safe evaluation context (safer than direct eval)
        const result = new Function('return ' + resolvedExpression)();
        if (isNaN(result) || !isFinite(result)) {
            return "Error"; // Handle calculation errors
        }
        return result;
    } catch (e) {
        console.error("Formula evaluation error:", e);
        return "Error";
    }
}

/**
 * Finds all cells that depend on the cell at changedCoord and recalculates their formulas.
 */
function recalculateDependencies(changedCoord) {
    const changedColIndex = parseInt(changedCoord.match(/[A-Z]+/)[0].toUpperCase().charCodeAt(0) - 'A'.charCodeAt(0));
    const changedRowIndex = parseInt(changedCoord.match(/[0-9]+/)[0]) - 1;

    // Iterate through all cells to check for dependencies (Simplified approach: Check every cell's formula)
    for (let r = 0; r < spreadsheetData.rows; r++) {
        for (let c = 0; c < spreadsheetData.cols; c++) {
            const coord = getCoord(c, r);

            if (coord === changedCoord) continue; // Skip the cell that was just changed

            const formula = spreadsheetData[coord].formula;
            if (formula && typeof formula === 'string' && formula.startsWith('=')) {
                // Check if this formula references the changed coordinate
                const regex = new RegExp(escapeRegExp(changedCoord), 'g');
                if (regex.test(formula)) {
                    calculateAndSetFormula(coord);
                }
            }
        }
    }
}

function recalculateAll() {
    for (let r = 0; r < spreadsheetData.rows; r++) {
        for (let c = 0; c < spreadsheetData.cols; c++) {
            const coord = getCoord(c, r);
            calculateAndSetFormula(coord);
        }
    }
}

function calculateAndSetFormula(coord) {
    const formulaString = spreadsheetData[coord].formula;
    if (!formulaString || !formulaString.startsWith('=')) return;

    const calculatedValue = calculateFormula(formulaString);

    // Update the model with the result
    spreadsheetData[coord].displayValue = calculatedValue;
    spreadsheetData[coord].value = String(calculatedValue); // Store as string representation of number/error
}


function initializeGrid() {
    const gridArea = document.getElementById('grid-area');
    if (!gridArea) return;

    // Clear existing content
    gridArea.innerHTML = '';
    spreadsheetData = {};
    spreadsheetData.rows = 20; // Fixed rows count
    spreadsheetData.cols = 10; // Fixed columns count (A to J)

    for (let r = 0; r < spreadsheetData.rows; r++) {
        const rowWrapper = document.createElement('div');
        rowWrapper.className = 'spreadsheet-row';
        rowWrapper.dataset.row = r + 1; // Store 1-based index

        // Row Label (Number)
        const labelDiv = document.createElement('div');
        labelDiv.className = 'row-label';
        labelDiv.textContent = r + 1;
        labelDiv.dataset.row = r + 1;
        rowWrapper.appendChild(labelDiv);

        // Cell Grid Container (A to J)
        const cellGridContainer = document.createElement('div');
        cellGridContainer.className = 'cell-grid';

        for (let c = 0; c < spreadsheetData.cols; c++) {
            const coord = getCoord(c, r);
            const cellDiv = document.createElement('div');
            cellDiv.className = 'cell';
            cellDiv.dataset.coord = coord;
            cellDiv.setAttribute('contenteditable', 'true'); // Make it editable

            // Initialize model data for the cell
            spreadsheetData[coord] = {
                value: '',
                displayValue: null,
                formula: '',
                color: '#ffffff'
            };

            // Attach event listeners to the newly created element
            cellDiv.addEventListener('click', handleCellClick);
            cellDiv.addEventListener('input', handleCellInput);

            cellGridContainer.appendChild(cellDiv);
        }
        rowWrapper.appendChild(cellGridContainer);
        gridArea.appendChild(rowWrapper);
    }
}


function handleCellClick(event) {
    const cell = event.currentTarget;
    const coord = cell.dataset.coord;

    if (!coord) return;

    // 1. Update selection state (R6, R7)
    clearSelection();
    selectCell(cell);

    // 2. Focus the element for immediate editing (R10)
    // We must ensure that when we focus, the cell is ready to receive input.
    if (event.type === 'click') {
        cell.focus();
    }
}

function handleCellInput(event) {
    const cell = event.currentTarget;
    const coord = cell.dataset.coord;
    let rawValue = event.target.value;

    // Update the model with the new raw value
    spreadsheetData[coord].value = rawValue;

    // If the user typed something, we must recalculate dependencies (R4)
    recalculateDependencies(coord);
}

function selectCell(cellElement) {
    clearSelection();
    cellElement.classList.add('selected-column-label'); // Using column label class for visual selection effect on cell itself
    // Note: In a real app, we'd manage separate classes for the actual selected cell background.
}

function clearSelection() {
    document.querySelectorAll('.cell').forEach(el => el.classList.remove('selected-column-label'));
}

function handleColumnLabelClick(event) {
    const label = event.currentTarget;
    const colLetter = label.dataset.col;

    if (!colLetter) return;

    // 1. Select the column label visually
    document.querySelectorAll('.col-header').forEach(el => el.classList.remove('selected-column-label'));
    label.classList.add('selected-column-label');

    // 2. Hide/Show all cells in this column
    const isHidden = !label.classList.contains('hidden');
    document.querySelectorAll(`.cell[data-coord^="${colLetter}"]`).forEach(cell => {
        if (isHidden) {
            cell.style.display = ''; // Show
        } else {
            cell.style.display = 'none'; // Hide
        }
    });

    // 3. Update state and UI
    spreadsheetData.columnVisibility[colLetter] = isHidden;
    saveState();
}

function handleRowNumberClick(event) {
    const label = event.currentTarget;
    const rowNumber = parseInt(label.dataset.row);

    if (isNaN(rowNumber)) return;

    // 1. Select the row label visually
    document.querySelectorAll('.row-label').forEach(el => el.classList.remove('selected-row-label'));
    label.classList.add('selected-row-label');

    // 2. Hide/Show all cells in this row
    const isHidden = !label.classList.contains('hidden');
    document.querySelectorAll('.spreadsheet-row[data-row="' + rowNumber + '"] .cell-grid .cell').forEach(cell => {
        if (isHidden) {
            cell.style.display = ''; // Show
        } else {
            cell.style.display = 'none'; // Hide
        }
    });

    // 3. Update state and UI
    spreadsheetData.rowVisibility[rowNumber] = isHidden;
    saveState();
}

function applyColor() {
    const colorPicker = document.getElementById('color-picker');
    const selectedCell = document.querySelector('.cell.selected-column-label'); // Assuming selection applies to the cell itself for simplicity here
    if (!selectedCell) return;

    const newColor = colorPicker.value;
    spreadsheetData[selectedCell.dataset.coord].color = newColor;
    selectedCell.style.backgroundColor = newColor;
}

function clearColumn() {
    const selectedColLabel = document.querySelector('.col-header.selected-column-label');
    if (!selectedColLabel) return;

    const colLetter = selectedColLabel.dataset.col;
    if (!confirm(`¿Está seguro de que desea eliminar la columna ${colLetter}? Esta acción es irreversible.`)) return;

    // 1. Update Model: Remove data for all cells in this column
    for (let r = 1; r <= spreadsheetData.rows; r++) {
        const coord = getCoord(selectedColLabel.charCodeAt(0) - 'A'.charCodeAt(0), r - 1);
        delete spreadsheetData[coord];
    }

    // 2. Update UI: Remove the column label and all cells associated with it
    selectedColLabel.remove();
    document.querySelectorAll(`.cell[data-coord^="${colLetter}"]`).forEach(cell => cell.remove());

    // 3. Adjust grid structure (This is complex in pure JS/CSS Grid, simplified by just removing elements)
    saveState();
}

function deleteColumn() {
    const selectedColLabel = document.querySelector('.col-header.selected-column-label');
    if (!selectedColLabel) return;

    const colLetter = selectedColLabel.dataset.col;
    if (!confirm(`¿Está seguro de que desea eliminar la columna ${colLetter}? Esta acción es irreversible.`)) return;

    // 1. Update Model: Remove data for all cells in this column
    for (let r = 1; r <= spreadsheetData.rows; r++) {
        const coord = getCoord(selectedColLabel.charCodeAt(0) - 'A'.charCodeAt(0), r - 1);
        delete spreadsheetData[coord];
    }

    // 2. Update UI: Remove the column label and all cells associated with it
    selectedColLabel.remove();
    document.querySelectorAll(`.cell[data-coord^="${colLetter}"]`).forEach(cell => cell.remove());

    saveState();
}

function hideColumn() {
    const selectedColLabel = document.querySelector('.col-header.selected-column-label');
    if (!selectedColLabel) return;

    const colLetter = selectedColLabel.dataset.col;
    const isHidden = !selectedColLabel.classList.contains('hidden');

    // Toggle visibility state in the model and UI
    selectedColLabel.classList.toggle('hidden', !isHidden);
    document.querySelectorAll(`.cell[data-coord^="${colLetter}"]`).forEach(cell => {
        if (isHidden) {
            cell.style.display = 'none'; // Hide
        } else {
            cell.style.display = ''; // Show
        }
    });

    spreadsheetData.columnVisibility[colLetter] = !isHidden;
    saveState();
}

function clearRow() {
    const selectedRowLabel = document.querySelector('.row-label.selected-row-label');
    if (!selectedRowLabel) return;

    const rowNumber = parseInt(selectedRowLabel.dataset.row);
    if (!confirm(`¿Está seguro de que desea borrar el contenido de la fila ${rowNumber}?`)) return;

    // 1. Update Model: Clear all cell values/formulas in this row
    for (let c = 0; c < spreadsheetData.cols; c++) {
        const coord = getCoord(c, rowNumber - 1);
        spreadsheetData[coord].value = '';
        spreadsheetData[coord].displayValue = null;
        spreadsheetData[coord].formula = '';
    }

    // 2. Update UI: Clear the content of all cells in this row
    document.querySelectorAll(`.cell[data-coord*="${rowNumber}"]`).forEach(cell => {
        cell.textContent = '';
        cell.dataset.formula = '';
        spreadsheetData[cell.dataset.coord].displayValue = null;
    });

    // 3. Recalculate all dependencies (though nothing changed, it's good practice)
    recalculateAll();
}

function deleteRow() {
    const selectedRowLabel = document.querySelector('.row-label.selected-row-label');
    if (!selectedRowLabel) return;

    const rowNumber = parseInt(selectedRowLabel.dataset.row);
    if (!confirm(`¿Está seguro de que desea eliminar la fila ${rowNumber}? Esta acción es irreversible.`)) return;

    // 1. Update Model: Remove data for all cells in this row
    for (let c = 0; c < spreadsheetData.cols; c++) {
        const coord = getCoord(c, rowNumber - 1);
        delete spreadsheetData[coord];
    }

    // 2. Update UI: Remove the row label and all cells associated with it
    selectedRowLabel.remove();
    document.querySelectorAll(`.spreadsheet-row[data-row="${rowNumber}"] .cell-grid`).forEach(container => container.remove());

    saveState();
}

function hideRow() {
    const selectedRowLabel = document.querySelector('.row-label.selected-row-label');
    if (!selectedRowLabel) return;

    const rowNumber = parseInt(selectedRowLabel.dataset.row);
    const isHidden = !selectedRowLabel.classList.contains('hidden');

    // Toggle visibility state in the model and UI
    selectedRowLabel.classList.toggle('hidden', !isHidden);
    document.querySelectorAll(`.spreadsheet-row[data-row="${rowNumber}"] .cell-grid`).forEach(container => {
        if (isHidden) {
            container.style.display = 'none'; // Hide
        } else {
            container.style.display = ''; // Show
        }
    });

    spreadsheetData.rowVisibility[rowNumber] = !isHidden;
    saveState();
}

function setupEventListeners() {
    // Column Label Listeners (A, B, C...)
    document.querySelectorAll('.col-header').forEach(label => {
        label.addEventListener('click', handleColumnLabelClick);
    });

    // Row Number Listeners (1, 2, 3...)
    document.querySelectorAll('.row-label').forEach(label => {
        label.addEventListener('click', handleRowNumberClick);
    });

    // Control Button Listeners
    document.getElementById('btn-clear-selection').addEventListener('click', clearSelection);
    document.getElementById('btn-delete-column').addEventListener('click', deleteColumn);
    document.getElementById('btn-hide-column').addEventListener('click', hideColumn);
    document.getElementById('btn-delete-row').addEventListener('click', deleteRow);
    document.getElementById('btn-hide-row').addEventListener('click', hideRow);
    document.getElementById('color-picker').addEventListener('input', applyColor);
    document.getElementById('btn-apply-color').addEventListener('click', applyColor);

    // Initial state setup (assuming we need to initialize the model structure)
    spreadsheetData.columnVisibility = {};
    spreadsheetData.rowVisibility = {};
}


function init() {
    setupEventListeners();
    initializeGrid();
    recalculateAll(); // Calculate initial empty grid state
}
